                      const totalEarlyLeaveMins = empRecords.reduce((sum: number, r: any) => sum + (r.early_leave_minutes || 0), 0);
                      const totalOvertimeMins = empRecords.reduce((sum: number, r: any) => sum + (r.overtime_minutes || 0), 0);
